"""Connected source HUD groups, sampling, aliases and ownership."""
import os
import subprocess
import tempfile
import unittest
from pathlib import Path
from haxe_test_support import HAXE_COMMAND
from source_bar_fixture_support import bar_fixture_files
from test_nv_multifield_routes import method
ROOT=Path(__file__).resolve().parents[2]

class SourceHUDBarIntegrationTest(unittest.TestCase):
 def test_actual_native_hud_groups_sample_once_and_preserve_draw_order(self):
  ps=(ROOT/'source/PlayState.hx').read_text(encoding='utf-8')
  methods='\n'.join(method(ps,m).replace('function ','public function ',1) for m in ['function isSourceHUDBarAlias(','function sourceHUDBarAlias(','function writeSourceHUDBarAlias(','function detachSourceHUDPiece(','function initializeSourceHUDBarGroups(','function updateSourceHUDIconPositions(','function sourceHUDHealthPercent('])
  files=bar_fixture_files()
  files['NightmareVisionHealthIcon.hx']='class NightmareVisionHealthIcon extends flixel.FlxSprite {public function new(){super();}public function updateIconAnim(v:Float):Void{}}'
  files['flixel/FlxG.hx']='package flixel;class FlxG {public static var height=720;}'
  files['flixel/FlxSprite.hx']=files['flixel/FlxSprite.hx'].replace('public function new(', 'public function screenCenter(?axis:Dynamic){x=(1280-width)/2;return this;}public function new(',1)
  files['Main.hx']=r'''import flixel.FlxBasic;import flixel.FlxSprite;import flixel.FlxG;
class PlayState {public static var globalSprites:Map<String,FlxSprite>=[];}
class NativeBar extends FlxSprite {public var percent:Float=17;public function new(){super();}}
class Text extends FlxSprite {public var text="";public function new(){super();}}
class Host {static inline var X=0;public var mode:Int;public var health:Float=1;public var healthBounds={min:0.,max:2.};public var songPositionBar:Float=.25;public var downscroll=false;public var camHUD:Dynamic={};public var healthBarBG=new FlxSprite();public var healthBar=new NativeBar();public var songPosBG=new FlxSprite();public var songPosBar=new NativeBar();public var songName=new Text();public var iconP1=new NightmareVisionHealthIcon();public var iconP2=new NightmareVisionHealthIcon();public var sourceHUDIconMode=0;public var score=new Text();public var timeBar:Dynamic;public var timeBarBG:FlxSprite;public var psychSourceHealthBar:PsychSourceBar;public var psychSourceTimeBar:PsychSourceBar;public var nightmareVisionSourceHealthBar:NightmareVisionBar;public var nightmareVisionSourceTimeBar:NightmareVisionBar;public var sourceHUDBarMode=0;public var sourceDetachedHUDPieces:Array<FlxBasic>=[];public var members:Array<FlxBasic>=[];public var playHUD:NightmareVisionHUDAdapter;public var iconOverride=false;public var nightmareVisionPaths={hudProfile:{name:"legacy-shared"},UI_PREFIX:"UI/core/"};public var nightmareVisionPrefs={view:{healthBarAlpha:.6,hideHud:false}};public var psychClientPrefs={data:{hideHud:false,healthBarAlpha:.7,timeBarType:"Time Left"}};public function new(m:Int){mode=m;songName.y=19;songName.height=32;members=[songPosBG,songPosBar,songName,healthBarBG,healthBar,iconP1,iconP2,score];}function bindSourceAttachmentClasses(i:Dynamic,n:Bool,?p:Dynamic):Void{}function bindSourceAlphabetClasses(i:Dynamic,p:Dynamic):Void{}function bindSourceHealthIconClass(i:Dynamic,n:Bool,?p:Dynamic):Void{}function isSourceHUDIconAlias(n:String)return false;function sourceHUDIconAlias(n:String):Dynamic return null;function writeSourceHUDIconAlias(n:String,v:Dynamic):Dynamic return v;function sourceNoteTimingMode()return mode;public function sourceBarOwner(n:Bool):SourceBarOwner return {image:Paths.image,antialiasing:()->true};function updateHealthColors():Void {}function remove(b:FlxBasic,splice:Bool):FlxBasic{members.remove(b);return b;}function insert(i:Int,b:FlxBasic):FlxBasic{members.insert(i,b);return b;}function add(b:FlxBasic):FlxBasic{members.push(b);return b;}__METHODS__
 public function createAdapter(){playHUD=new NightmareVisionHUDAdapter({parent:this,healthFill:healthBar,healthBackground:nightmareVisionSourceHealthBar.bg,sourceHealthBar:nightmareVisionSourceHealthBar,sourceTimeBar:nightmareVisionSourceTimeBar,iconP1:iconP1,iconP2:iconP2,scoreText:score,songFill:songPosBar,songBackground:nightmareVisionSourceTimeBar.bg,timeText:songName,showTime:true});}
 public function tick(){for(member in members)if(member!=null&&member.exists&&member.active)member.update(.016);}
}
class Main {static function ok(v:Bool,m:String):Void if(!v)throw m;static function main(){for(mode in [1,2]){var h=new Host(mode);var originalHealth=h.healthBar;var originalBackground=h.healthBarBG;h.initializeSourceHUDBarGroups();var group:Dynamic=h.sourceHUDBarAlias("healthBar");var time:Dynamic=h.sourceHUDBarAlias("songPosBar");ok(h.members.indexOf(group)>=0&&h.members.indexOf(time)>=0&&h.members.indexOf(originalHealth)<0&&h.members.indexOf(originalBackground)<0,"actual groups replace native pieces");ok(h.members.indexOf(group)<h.members.indexOf(h.iconP1)&&h.members.indexOf(time)<h.members.indexOf(h.songName),"source bar/icon and time/label draworder");ok(h.sourceHUDBarAlias("healthBarBG")==group.bg&&h.sourceHUDBarAlias("timeBar")==time&&h.sourceHUDBarAlias("timeBarBG")==time.bg,"shared actual aliases");ok(h.members.indexOf(group.leftBar)<0&&h.members.indexOf(group.bg)<0,"no duplicate root children");var calls=0;group.valueFunction=()->{calls++;return .5;};h.tick();ok(calls==1&&group.percent==25&&group.leftBar.updates==1,"one source sample and one child update perstatepass");group.updateBar();ok(calls==1,"updateBar does notsample");group.enabled=false;h.tick();ok(calls==1&&group.percent==25&&group.leftBar.updates==2,"disabled source still updates children no sample");group.barWidth=150;group.barOffset.x=11;group.updateBar();h.updateSourceHUDIconPositions();ok(h.iconP1.x==group.barCenter-26&&h.iconP2.x==group.barCenter-127,"physical boundary positions even disabled");if(mode==2){h.createAdapter();ok(h.playHUD.healthBar==group&&h.playHUD.members[0]==group&&h.playHUD.members.indexOf(group.bg)<0,"adapter same physical group no children");h.playHUD.onHealthChange(.9);ok(calls==2&&group.percent==25,"healthcallback explicitlysamples even disabled");group.valueFunction=null;var threw=false;try h.playHUD.onHealthChange(1)catch(_:Dynamic)threw=true;ok(threw,"source null callbackthrows");var tcalls=0;time.valueFunction=()->{tcalls++;return .75;};time.enabled=false;time.percent=42;h.playHUD.updateTimer(1000,2000,0,"Time Left",false,false,false);ok(tcalls==0&&time.percent==42&&h.songPositionBar==.5,"timerpublishesfraction withoutoverwriting disabled/custombar");time.enabled=true;h.tick();ok(tcalls==1&&time.percent==75,"naturalgroupupdate samples authoredcallback");h.playHUD.release();ok(group.destroyed==0&&group.leftBar.destroyed==0,"adapter release not ownerdestruction");}var replaced:Dynamic=mode==1?cast new PsychSourceBar(0,0,"other",null,0,1,h.sourceBarOwner(false)):cast new NightmareVisionBar(0,0,"other",null,0,1,h.sourceBarOwner(true));h.writeSourceHUDBarAlias("healthBar",replaced);ok(h.sourceHUDBarAlias("healthBar")==replaced&&h.members.indexOf(group)>=0&&h.members.indexOf(replaced)<0,"publicpointerreplacement doesnot rewrite existingdisplay");h.writeSourceHUDBarAlias("healthBar",null);ok(h.sourceHUDBarAlias("healthBar")==null&&h.isSourceHUDBarAlias("healthBar"),"source null neverhiddennativealias");for(piece in h.sourceDetachedHUDPieces)piece.destroy();for(member in h.members)member.destroy();ok(originalHealth.destroyed==1&&originalBackground.destroyed==1&&group.leftBar.destroyed==1,"separate native/group owners destroy once");}}}
'''.replace('__METHODS__',methods)
  # Production adapter selects typed actual groups under the real flixel define.
  with tempfile.TemporaryDirectory(dir=ROOT/'tmp') as tmp:
   work=Path(tmp)
   for name,content in files.items():
    p=work/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content,encoding='utf-8')
   env=os.environ.copy();env['HAXELIB_PATH']=str(ROOT/'.haxelib');env['NEKOPATH']=str(ROOT/'.tools/neko');env['PATH']=str(ROOT/'.tools/haxe')+os.pathsep+str(ROOT/'.tools/neko')+os.pathsep+env.get('PATH','')
   for target in [['--interp'],['-cpp',str(work/'cpp'),'-D','no-compilation']]:
    result=subprocess.run([*HAXE_COMMAND,'-D','flixel','-cp',str(ROOT/'source'),'-cp',tmp,'-main','Main',*target],cwd=ROOT,env=env,capture_output=True,text=True,timeout=40)
    self.assertEqual(result.returncode,0,(result.stdout+result.stderr)[-6000:])

 def test_actual_iris_and_psych_bridge_aliases_imports_and_lua_property_parts(self):
  ps=(ROOT/'source/PlayState.hx').read_text(encoding='utf-8')
  methods='\n'.join(method(ps,m).replace('function ','public function ',1) for m in ['function isSourceHUDBarAlias(','function sourceHUDBarAlias(','function writeSourceHUDBarAlias(','function bindSourceHUDBarAliases(','function bindSourceBarClass(','function bindSourceHealthValues(','function compatPathIndex(','function compatReadPathPart(','function compatWritePathPart('])
  files=bar_fixture_files()
  files['flixel/math/FlxPoint.hx']=files['flixel/math/FlxPoint.hx'].replace('public function new(', 'public static function get(x=0.,y=0.)return new FlxPoint(x,y);public function new(',1)
  files['PsychBaseStageActorGroupCompat.hx']='class PsychBaseStageActorGroupCompat {}'
  files['Main.hx']=r'''import flixel.util.helpers.FlxBounds;class PlayState {} class EngineCompat {public static function psychHealthColorArray(a:Dynamic,b:Dynamic,c:Dynamic,d:Dynamic,e:Dynamic,f:Dynamic):Array<Int> return [];}class HUD {public var healthBar:NightmareVisionBar;public var timeBar:NightmareVisionBar;public function new(){}}
class Host {public var health:Float=1;public var mode=1;public var sourceHUDBarMode=1;public var healthBar:Dynamic={native:true};public var healthBarBG:Dynamic;public var timeBar:Dynamic;public var timeBarBG:Dynamic;public var songPosBar:Dynamic;public var songPosBG:Dynamic;public var boyfriend:Dynamic;public var dad:Dynamic;public var gf:Dynamic;public var iconP1:Dynamic;public var iconP2:Dynamic;public var psychSourceHealthBar:PsychSourceBar;public var psychSourceTimeBar:PsychSourceBar;public var nightmareVisionSourceHealthBar:NightmareVisionBar;public var nightmareVisionSourceTimeBar:NightmareVisionBar;public var playHUD:HUD;public function new(m:Int){mode=sourceHUDBarMode=m;var o=sourceBarOwner(m==2);if(m==1){psychSourceHealthBar=new PsychSourceBar(0,0,"health",null,0,2,o);psychSourceTimeBar=new PsychSourceBar(0,0,"time",null,0,1,o);}else{nightmareVisionSourceHealthBar=new NightmareVisionBar(0,0,"health",null,0,2,o);nightmareVisionSourceTimeBar=new NightmareVisionBar(0,0,"time",null,0,1,o);playHUD=new HUD();playHUD.healthBar=nightmareVisionSourceHealthBar;playHUD.timeBar=nightmareVisionSourceTimeBar;}}function bindSourceAttachmentClasses(i:Dynamic,n:Bool,?p:Dynamic):Void{}function bindSourceAlphabetClasses(i:Dynamic,p:Dynamic):Void{}function bindSourceHealthIconClass(i:Dynamic,n:Bool,?p:Dynamic):Void{}function isSourceHUDIconAlias(n:String)return false;function sourceHUDIconAlias(n:String):Dynamic return null;function writeSourceHUDIconAlias(n:String,v:Dynamic):Dynamic return v;function sourceNoteTimingMode()return mode;function sourceBarOwner(n:Bool,?paths:Dynamic):SourceBarOwner return {image:Paths.image,antialiasing:()->true};function compatCoercePropertyValue(t:Dynamic,k:String,v:Dynamic):Dynamic return v;__METHODS__}
class Main {static function ok(v:Bool,m:String):Void if(!v)throw m;static function main(){for(mode in [1,2]){var host=new Host(mode);var interp=new NightmareVisionScriptInterp(host);interp.variables.set("game",host);interp.variables.set("PlayState",PlayState);interp.bindClassParent(PlayState);interp.variables.set("healthBar",host.healthBar);host.bindSourceBarClass(interp,mode==2);var parser=new NightmareVisionScriptParser();interp.execute(parser.parseString("same = healthBar == game.healthBar && game.healthBarBG == healthBar.bg && game.timeBar == songPosBar && PlayState.healthBar == healthBar; made = new Bar(7, 9, 'owner-image', null, -2, 4);"));ok(interp.variables.get("same")==true,"Irisbare/game/class/time/background identity");var actual=host.sourceHUDBarAlias("healthBar");ok(host.compatReadPathPart(host,"healthBar")==actual&&host.compatReadPathPart(host,"healthBarBG")==Reflect.getProperty(actual,"bg"),"actualLua property receiver identity");var made:Dynamic=interp.variables.get("made");ok(Reflect.getProperty(made,"x")==7&&Reflect.getProperty(made,"bounds").min == -2,"constructor factory actual source group");ok(interp.importBindings.get(mode==2?"funkin.objects.Bar":"objects.Bar")==interp.variables.get("Bar"),"import actualclass identity");ok(host.compatWritePathPart(host,"healthBar",made)&&host.sourceHUDBarAlias("healthBar")==made,"Lua source pointer writes avoidhiddennative");interp.execute(parser.parseString("again = game.healthBar == healthBar && PlayState.healthBar == healthBar; game.healthBar = null; empty = healthBar == null && PlayState.healthBar == null;"));ok(interp.variables.get("again")==true&&interp.variables.get("empty")==true,"current replacement/null aliases");ok(host.healthBar.native==true,"typednative HUDfield unchanged");if(mode==2)ok(interp.importBindings.exists("funkin.game.IUiSprite"),"source interface import");interp.release();}var h=new Host(1);var bridge=new SourceIrisBridge(h);bridge.variables.set("game",h);h.bindSourceBarClass(bridge.evaluator,false);bridge.evaluate("import objects.Bar; actual = game.healthBar == healthBar; constructed = new Bar(1, 2, 'psych-owner');", "probe.hx");ok(bridge.variables.get("actual")==true&&Std.isOfType(bridge.variables.get("constructed"),PsychSourceBar),"realPsychplainbridge actualgroup imports");}}
'''.replace('__METHODS__',methods)
  with tempfile.TemporaryDirectory(dir=ROOT/'tmp') as tmp:
   work=Path(tmp)
   for name,content in files.items():
    path=work/name;path.parent.mkdir(parents=True,exist_ok=True);path.write_text(content,encoding='utf-8')
   result=subprocess.run([*HAXE_COMMAND,'-cp',str(ROOT/'source'),'-cp',str(ROOT/'.haxelib/hscript/2,5,0'),'-cp',str(ROOT/'.haxelib/hscript-iris/1,1,3'),'-cp',tmp,'--run','Main'],cwd=ROOT,capture_output=True,text=True,timeout=40)
   self.assertEqual(result.returncode,0,(result.stdout+result.stderr)[-6000:])
